from collections import defaultdict
# d = defaultdict(int)で0で初期化
# d = defaultdict(lambda: 100)で100で初期化
import sys
input = sys.stdin.readline
n, m = map(int, input().split())
es = [defaultdict(int) for _ in range(n)]
for i in range(m):
    a, b = map(int, input().split())
    a -= 1
    b -= 1
    es[a][b] += 1
    es[b][a] += 1
    if es[a][b] == 2:
        es[a].pop(b)
        es[b].pop(a)

def dfs(v, p, r):
    for i in es[v]:
        if i != p:
            es[i].pop(v)
            es[v].pop(i)
            if i == r:
                return - 1
            else:
                return dfs(i, v, r)
    return - 2

for i in range(n):
    if es[i]:
        if dfs(i, -1, i) == -2:
            print("NO")
            exit()
print("YES")

import sys

input = sys.stdin.readline

def main():
    N, M = map(int, input().split())
    S = input()[::-1]

    ans = []
    i = 0

    if S[0] == '1': print(-1); sys.exit()

    while i < N:
        for j in range(min(M,N-i), 0, -1):
            if  S[i+j] == '0': break
        else: print(-1); sys.exit()

        ans.append(j)
        i += j

    print(' '.join(map(str, ans[::-1])))

if __name__ == '__main__':
    main()

