root = [[] for i in range(n)]
for _ in range(n-1):
    a, b = (int(x) for x in input().split())
    root[b-1].append(a-1)
    root[a-1].append(b-1)

stack=[0]
check = [-1]*n
check[0] = 0
count1 = 0
while len(stack):
    v = stack.pop()
    for i in root[v]:
        if i == n-1:
            continue
        if check[i] == -1:
            check[i]=1
            stack.append(i)
            count1 += 1

stack=[n-1]
check = [-1]*n
check[n-1] = 0
count2 = 0
while len(stack):
    v = stack.pop()
    for i in root[v]:
        if i == 0:
            continue
        if check[i] == -1:
            check[i]=1
            stack.append(i)
            count2 += 1


