        return 0
    if x[len(x)-1] == '?':
        return ab(x[:-1])*3 \
                +a[len(x)-1-1]*pow(3,q[len(x)-1-1])\
                +q[len(x)-1-1]*pow(3,q[len(x)-1-1]-1)
    elif x[len(x)-1] == 'B':
        return  ab(x[:-1]) \
                +a[len(x)-1-1]*pow(3,q[len(x)-1-1])\
                +q[len(x)-1-1]*pow(3,q[len(x)-1-1]-1)
    else:
        return ab(x[:-1])
