import bisect
import itertools
N = int(input())
S = input()

cache = {}
for i in range(N):
    if S[i] in cache:
        cache[S[i]].append(i)
    else:
        cache[S[i]] = [i]

result = 0

route = []
for k,v in cache.items():
    route.append(len(v) - bisect.bisect_left(v, 0))
for i in range(1,28):
    xxx = result
    #i種類取り出して掛け算した値を足し込む
    for cb in itertools.combinations(route, i):
        num = 1
        for x in cb:
            num = num * x
        result += num
    if xxx == result:
        break
print(result)

