n, q = map(int, input().split())
tree = defaultdict(list)
for _ in range(n - 1):
    a, b = map(int, input().split())
    tree[a].append(b)

counters = [0] * (n + 1)
operations = []
for _ in range(q):
    p, x = map(int, input().split())
    operations.append((p, x))

def dfs(node, parent, x):
    counters[node] += x
    for child in tree[node]:
        if child != parent:
            dfs(child, node, x)

for p, x in operations:
    dfs(p, -1, x)

