def is_palindrome(s):
  return s == s[::-1]

def min_operations(s):
  n = len(s)
  if is_palindrome(s):
    return 0

  left = 0
  right = n - 1
  operations = 0
  while left < right:
    if s[left] == s[right]:
      left += 1
      right -= 1
    else:
      operations += 1
      left += 1
  return operations if operations <= n else -1

s = input()
print(min_operations(s))

