def changeblack(a,n):
    t = n
    for i in range(0,49):
        if t <= 0:
            break
        elif i % 2 == 0:
            for j in range(0,min(50,t)*2):
                if j % 2 == 0:
                    a[i][j] = '.'
            t -= 50


    return a


def changewhite(a,n):
    t = n
    for i in range(51,100):
        if t <= 0:
            break
        elif i % 2 == 0:
            for j in range(0,min(50,t)*2):
                if j % 2 == 0:
                    a[i][j] = '#'
            t -= 50

    return a
