import sys
import math
from collections import defaultdict
from collections import deque
from fractions import Fraction

sys.setrecursionlimit(1000000)
MOD = 10 ** 9 + 7
input = lambda: sys.stdin.readline().strip()
NI = lambda: int(input())
NMI = lambda: map(int, input().split())
NLI = lambda: list(NMI())
SI = lambda: input()


def main():
    N = NI()
    AB = defaultdict(int)
    Y, Z = 0, 0
    for i in range(N):
        a, b = NMI()
        if a == b == 0:
            Z += 1
            continue
        if b == 0:
            Y += 1
            continue

        if Fraction(a, b) in AB:
            AB[Fraction(a, b)] += 1
        else:
            AB[Fraction(a, b)] = 1

    C = defaultdict(lambda: ())
    ans = 1
    for ab, k in list(AB.items()):
        a = ab.numerator
        b = ab.denominator
        if a > 0:
            if Fraction(-b, a) in AB:
                t = AB[Fraction(-b, a)]
            else:
                t = 0
        elif a < 0:
            if Fraction(b, -a) in AB:
                t = AB[Fraction(b, -a)]
            else:
                t = 0
        else:
            t = Y
        C[(a, b)] = (k, t)

    for k, t in list(C.values()):
        tmp = pow(2, k, MOD) + pow(2, t, MOD) - 1
        ans = ans * tmp % MOD
    print((ans + Z - 1)%MOD)


if __name__ == "__main__":
    main()

import math


def inputIntList():
    return [int(s) for s in input().split()]


def inputInt():
    return int(input())


def main():
    N = inputInt()
    a = inputIntList()
    if len(a) == 1:
        return 0
    ans = 0
    look = 0
    current = 0
    while current < len(a):
        if look >= N:
            return ans
        if look + 1 == a[current]:
            look += 1
            current += 1
        else:
            ans += 1
            current += 1
    if look < N:
        return -1
    return ans


if __name__ == "__main__":
    print(main())

def is_keyence(s):
  if s == "keyence":
    return True
  for i in range(len(s)):
    for j in range(i+1, len(s)+1):
      if s[:i] + s[j:] == "keyence":
        return True
  return False

