from functools import lru_cache
@lru_cache(None)
def dfs(fukasa,ansuka1):
    if fukasa == 0:
        if ans[0] == 1:
            return True
        else:
            return False

    mi = a[fukasa] -(-ansuka1//2)
    ans[fukasa] = mi
    if not dfs(fukasa-1,ansuka1):
        return False

    tmp = a[fukasa]+ansuka1
    tmp = min(tmp,2**fukasa)

    while tmp >= a[fukasa] -(-ansuka1//2):
        if dfs(fukasa-1, ansuka1):
            ans[fukasa]=tmp
            break
        tmp -= 1
    else:
        return False
    return True

