    for i in range(H):
        if h_div >> i & 1:
            cut.append(i+1)
            count += 1
    cut.append(H)
    if count > ans:
        continue

    left = 0
    for right in range(1, W+1):
        white = 0
        for i in range(len(cut)-1):
            white = max(white, countWhite(cut[i], cut[i+1], left, right))

        if white > K:
            left = right
            count += 1
            if count > ans:
                break
    else:
        if count < ans:
            ans = count

