def count_digits(n):
  return len(str(n))

def solve(n):
  total_count = 0
  power = 0
  while n > 0:
    if n % 10 != 0:
      total_count += count_digits(n)
      n -= 10**power
    else:
      n //= 10
      power += 1
  return total_count

