for i in range(n):
    for j in range(i + 1, n):
        p = xy[j][0] - xy[i][0]
        q = xy[j][1] - xy[i][1]
        if p == 0 and q == 0:
            continue
        cost = 1
        visited = set([i, j])
        for k in range(n):
            if k in visited:
                continue
            if (xy[k][0] - p, xy[k][1] - q) in xy:
