def solve(n, m, k):
    MOD = 998244353
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = (dp[i][j] + dp[i - 1][j] * (m - 1)) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
    return dp[n][k]
n, m, k = map(int, input().split())
print(solve(n, m, k))

