import math

def count_divisors(n):
  cnt = 0
  for i in range(1, int(math.sqrt(n)) + 1):
    if n % i == 0:
      cnt += 1
      if i != n // i:
        cnt += 1
  return cnt

def factorial(n):
  fact = 1
  for i in range(1, n + 1):
    fact *= i
  return fact

def count_shichi_go(n):
  fact = factorial(n)
  cnt = 0
  for i in range(1, fact + 1):
    if count_divisors(i) == 75:
      if fact % i == 0:
        cnt += 1
  return cnt

