from functools import lru_cache

N = int(input())
K = int(input())
DP = [[0] * (K + 1) for _ in range(len(str(N)) + 1)]

@lru_cache(None)
def calc(a, b):
    if a < 10:
        if b == 0:
            return 1
        if b == 1:
            return a
        else:
            return 0
    if DP[a][b] != 0:
        return DP[a][b]
    x = a % 10
    if b >= 1:
        ans = x * calc(a // 10, b - 1) + (9 - x) * calc(a // 10 - 1, b - 1)
    else:
        ans = 0
    ans += calc(a//10, b)
    DP[a][b] = ans
    return ans

print(calc(N, K))

import heapq
from collections import defaultdict

def dijkstra(graph, start, fuel_limit):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = [(0, start, 0)]  # (distance, node, refuel_count)
    while queue:
        dist, node, refuel_count = heapq.heappop(queue)
        if dist > distances[node]:
            continue
        for neighbor, distance in graph[node].items():
            new_dist = dist + distance
            new_refuel_count = refuel_count
            if new_dist > fuel_limit:
                new_dist = distance
                new_refuel_count += 1
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heapq.heappush(queue, (new_dist, neighbor, new_refuel_count))
    return distances

def main():
    N, M, L = map(int, input().split())
    graph = defaultdict(dict)
    for _ in range(M):
        A, B, C = map(int, input().split())
        graph[A][B] = C
        graph[B][A] = C
    Q = int(input())
    for _ in range(Q):
        s, t = map(int, input().split())
        distances = dijkstra(graph, s, L)
        if distances[t] == float('inf'):
            print(-1)
        else:
            print(distances[t])

if __name__ == '__main__':
    main()

