def solve(n, k, segments):
    mod = 998244353
    dp = [0] * (n + 1)
    dp[1] = 1
    s = set()
    for l, r in segments:
        for i in range(l, r + 1):
            s.add(i)
    for i in range(2, n + 1):
        for d in s:
            if i - d >= 1:
                dp[i] = (dp[i] + dp[i - d]) % mod
    return dp[n]


