def is_tree(n, edges):
  """
  Checks if the given edges form a tree.
  """
  if len(edges) != n - 1:
    return False
  parent = [None] * (n + 1)
  for u, v in edges:
    if parent[u] is not None and parent[v] is not None:
      return False
    if parent[u] is None:
      parent[u] = v
    else:
      parent[v] = u
  return True

def check_tree(n, edges):
  """
  Checks if the given edges form a tree and if all edge weights are even.
  """
  if not is_tree(n, edges):
    return False
  edge_counts = [0] * (n + 1)
  for u, v in edges:
    edge_counts[u] += 1
    edge_counts[v] += 1
  for count in edge_counts[1:]:
    if count % 2 != 0:
      return False
  return True

