def solve(M, K):
  N = 1 << (M + 1)
  a = [0] * N
  used = [False] * (1 << M)
  for i in range(N // 2):
    for j in range(1 << M):
      if not used[j]:
        a[2 * i] = j
        a[2 * i + 1] = j ^ K
        used[j] = True
        break
  if all(used):
    return a
  else:
    return [-1]

