def is_achievable(s, x, y):
    direction = 0  # 0: right, 1: up, 2: left, 3: down
    current_x = 0
    current_y = 0
    for instruction in s:
        if instruction == 'F':
            if direction == 0:
                current_x += 1
            elif direction == 1:
                current_y += 1
            elif direction == 2:
                current_x -= 1
            else:
                current_y -= 1
        else:
            direction = (direction + 1) % 4
    return current_x == x and current_y == y

