def count_subsequences(s, t):
    n = len(s)
    m = len(t)
    MOD = 10**9 + 7

    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(m + 1):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1] + MOD) % MOD
            if s[i - 1] == t[j - 1]:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

    return dp[n][m]

