def solve(s, t):
    if len(s) != len(t):
        return "No"
    count = {}
    for c in s:
        if c not in count:
            count[c] = 0
        count[c] += 1
    for c in t:
        if c not in count:
            return "No"
        count[c] -= 1
    for v in count.values():
        if v != 0:
            return "No"
    return "Yes"

