def mod_pow(a, b, mod):
    if b == 0:
        return 1
    elif b % 2 == 0:
        return mod_pow(a * a % mod, b // 2, mod)
    else:
        return a * mod_pow(a, b - 1, mod) % mod

def comb(n, r, mod):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    return (comb(n - 1, r - 1, mod) + comb(n - 1, r, mod)) % mod

