    max_score = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for k in range(1, m + 1):
                score = 0
                for a, b, c, d in conditions:
                    if a == i and b == j and k - i == c:
                        score += d
                max_score = max(max_score, score)
    return max_score

