for i in range(1, k + 1):
    total += (n * m * mod_pow(k - 1, i - 1, mod) * mod_pow(n * m - k, k - i, mod) * i * (k - i)) % mod
total = (total * comb(n * m, k, mod)) % mod
print(total)

