def solve(n):
    mod = 10**9 + 7
    dp = [[0] * 4 for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(4):
            for k in range(4):
                if (j == 0 and k == 1) or (j == 1 and k == 2) or (j == 2 and k == 0):
                    continue
                dp[i][k] = (dp[i][k] + dp[i - 1][j]) % mod
    return sum(dp[n]) % mod

