    if A[h][W - 1] % 2 == 1:
        A[h + 1][W - 1] += 1
        ans.append((h + 1, W, h + 2, W))

if A[H][W - 1] % 2 == 1:
    ans.pop()

print(len(ans))
for h, w, nh, nw in ans:
    print(h, w, nh, nw)

