def count_k(n):
  count = 0
  for k in range(2, n + 1):
    temp = n
    while temp >= k:
      if temp % k == 0:
        temp //= k
      else:
        temp -= k
    if temp == 1:
      count += 1
  return count

n = int(input())
print(count_k(n))

n,m = [int(i) for i in input().split()]
x = [int(i) for i in input().split()]
y = [int(i) for i in input().split()]

S = 0
MOD = 10**9+7

for i in range(n):
    for j in range(i+1,n):
        for k in range(m):
            for l in range(k+1,m):
                s = (x[j]-x[i])*(y[l]-y[k])
                S = (S + s) % MOD

print(S)

def solve():
  N = int(input())
  A = list(map(int, input().split()))
  if A[N] == 0:
    return -1
  ans = 1
  for i in range(N):
    if A[i] == 0:
      return -1
    ans += A[i]
    A[i + 1] -= 2 * A[i]
  return ans

print(solve())

